"use strict";(self.webpackChunkstrapi_docs=self.webpackChunkstrapi_docs||[]).push([[15143],{20945:e=>{e.exports=JSON.parse('{"tag":{"label":"Rest API","permalink":"/tags/rest-api","allTagsPath":"/tags","count":29,"items":[{"id":"cms/configurations/api","title":"API calls configuration","description":"Strapi\'s default API parameters can be configured.","permalink":"/cms/configurations/api"},{"id":"cms/backend-customization","title":"Back-end customization","description":"All elements of Strapi\'s back end, like routes, policies, middlewares, controllers, services, models, requests, responses, and webhooks, can be customized.","permalink":"/cms/backend-customization"},{"id":"cms/api/content-api","title":"Content API","description":"Learn more about Strapi 5\'s Content API","permalink":"/cms/api/content-api"},{"id":"cms/backend-customization/controllers","title":"Controllers","description":"Controllers bundle actions that handle business logic for each route within Strapi\u2019s MVC pattern. This documentation demonstrates generating controllers, extending core ones with createCoreController, and delegating heavy logic to services.","permalink":"/cms/backend-customization/controllers"},{"id":"cms/backend-customization/examples/services-and-controllers","title":"Custom services and controllers","description":"Learn how to authenticate use custom services and controllers using our FoodAdvisor example","permalink":"/cms/backend-customization/examples/services-and-controllers"},{"id":"cms/error-handling","title":"Error handling","description":"With Strapi\'s error handling feature it\'s easy to send and receive errors in your application.","permalink":"/cms/error-handling"},{"id":"cms/api/rest/filters","title":"Filters","description":"Use Strapi\'s REST API to filter the results of your requests.","permalink":"/cms/api/rest/filters"},{"id":"cms/api/rest/guides/populate-creator-fields","title":"How to populate creator fields","description":"Learn how to populate creator fields such as createdBy and updatedBy by creating a custom controller that leverages the populate parameter.","permalink":"/cms/api/rest/guides/populate-creator-fields"},{"id":"cms/api/rest/interactive-query-builder","title":"Interactive Query Builder","description":"Use an interactive tool that leverages the querystring library to build your query URL","permalink":"/cms/api/rest/interactive-query-builder"},{"id":"cms/api/rest/locale","title":"Locale","description":"Browse the REST API reference for the locale parameter to take advantage of the Internationalization feature through REST.","permalink":"/cms/api/rest/locale"},{"id":"cms/migration/v4-to-v5/breaking-changes/no-locale-all","title":"locale=all can not be used to query all locales","description":"In Strapi 5, it\'s no longer possible to get all localized versions with the \'?locale=all\' parameter.","permalink":"/cms/migration/v4-to-v5/breaking-changes/no-locale-all"},{"id":"cms/backend-customization/middlewares","title":"Middlewares","description":"Middlewares alter the request or response flow at application or API levels. This documentation distinguishes global versus route middlewares and illustrates custom implementations with generation patterns.","permalink":"/cms/backend-customization/middlewares"},{"id":"cms/backend-customization/models","title":"Models","description":"Strapi models (i.e. content-types, components, and dynamic zones) define a representation of the content structure.","permalink":"/cms/backend-customization/models"},{"id":"cms/migration/v4-to-v5/breaking-changes/no-shared-population-strategy-components-dynamic-zones","title":"No shared population strategy for components & dynamic zones","description":"In Strapi 5, the shared population strategy is not supported anymore, so components and dynamic zones must be explicitly populated using `on` fragments.","permalink":"/cms/migration/v4-to-v5/breaking-changes/no-shared-population-strategy-components-dynamic-zones"},{"id":"cms/api/rest/parameters","title":"Parameters","description":"Use API parameters to refine your Strapi REST API queries.","permalink":"/cms/api/rest/parameters"},{"id":"cms/backend-customization/policies","title":"Policies","description":"Strapi policies are functions that execute specific logic on each request before it reaches the controller. Policies can be customized according to your needs.","permalink":"/cms/backend-customization/policies"},{"id":"cms/api/rest/populate-select","title":"Populate and Select","description":"Use Strapi\'s REST API to populate or select certain fields.","permalink":"/cms/api/rest/populate-select"},{"id":"cms/api/rest/relations","title":"Relations","description":"Use the REST API to manage the order of relations","permalink":"/cms/api/rest/relations"},{"id":"cms/backend-customization/requests-responses","title":"Requests and Responses","description":"Learn more about requests and responses for Strapi, the most popular headless CMS.","permalink":"/cms/backend-customization/requests-responses"},{"id":"cms/api/rest/guides/intro","title":"REST API Guides","description":"Deep dive into some specific REST API topics using guides that extensively explain some use cases or give step-by-step instructions.","permalink":"/cms/api/rest/guides/intro"},{"id":"cms/api/rest","title":"REST API reference","description":"Interact with your Content-Types using the REST API endpoints Strapi generates for you.","permalink":"/cms/api/rest"},{"id":"cms/backend-customization/routes","title":"Routes","description":"Strapi routes handle requests to your content and are auto-generated for your content-types. Routes can be customized according to your needs.","permalink":"/cms/backend-customization/routes"},{"id":"cms/backend-customization/services","title":"Services","description":"Strapi services are a set of reusable functions, useful to simplify controllers logic.","permalink":"/cms/backend-customization/services"},{"id":"cms/api/rest/sort-pagination","title":"Sort and Pagination","description":"Use Strapi\'s REST API to sort or paginate your data.","permalink":"/cms/api/rest/sort-pagination"},{"id":"cms/api/rest/status","title":"Status","description":"Use Strapi\'s REST API to work with draft or published versions of your documents.","permalink":"/cms/api/rest/status"},{"id":"cms/migration/v4-to-v5/breaking-changes/new-response-format","title":"Strapi 5 has a new, flattened response format for API calls","description":"In Strapi 5, the response format has been simplified and flattened, and attributes of requested content are no longer wrapped in an attributes object.","permalink":"/cms/migration/v4-to-v5/breaking-changes/new-response-format"},{"id":"cms/api/rest/guides/understanding-populate","title":"Understanding populate","description":"Learn what populating means and how you can use the populate parameter in your REST API queries to add additional fields to your responses.","permalink":"/cms/api/rest/guides/understanding-populate"},{"id":"cms/api/rest/upload","title":"Upload files","description":"Learn how to use the /api/upload endpoints to upload files to Strapi with the REST API.","permalink":"/cms/api/rest/upload"},{"id":"cms/backend-customization/webhooks","title":"Webhooks","description":"Strapi webhooks are user-defined HTTP callbacks used by an application to notify other applications that an event occurred.","permalink":"/cms/backend-customization/webhooks"}],"unlisted":false}}')}}]);